/bin/bash -c "python3 - <<'PY'
# Enumerate feasible confusion matrices in the paper's two-group example.
# FNRs s,t each span [0,5/7], FPR_L=2/7+3s/7, FPR_R=7t/3.
# FNR_R actually spans [0,3/7].
def eta(a,b):
 if b<a: return 1-b/a
 if b>a: return (b-a)/(1-a)
 return 0.0

def row(a,b,wa,wb):
 return min(wb*eta(a,b),wa*eta(b,a))
steps=600
betas=[0,.25,.5,.59,.6,.61,.7,.9,1]
best={beta:(float('inf'),None,None,None,None) for beta in betas}
constrained=(float('inf'),None,None,None)
for i in range(steps+1):
 s=(5/7)*i/steps
 a=2/7+3*s/7
 for j in range(steps+1):
  t=(3/7)*j/steps
  b=7*t/3
  e=.35*a+.15*b+.15*s+.35*t
  u=row(a,b,.35,.15)+row(s,t,.15,.35)
  if e<=.2+1e-12 and u<constrained[0]: constrained=(u,e,s,t)
  for beta in betas:
   val=beta*u+(1-beta)*e
   if val<best[beta][0]: best[beta]=(val,u,e,s,t)
print('grid size',(steps+1)**2)
for beta,result in best.items(): print('beta',beta,'objective,u,error,FNR_L,FNR_R',tuple(round(x,7) for x in result))
print('Minimum grid unfairness subject to error<=0.2:', constrained)
PY"
